{"mode": "replace", "new_string": "    // Calcola il bonus produzione totale dalle ricerche LF per un set di pianeti.
    // Le ricerche LF aumentano la produzione di tutti i pianeti (bonus globale).
    // Ogni pianeta contribuisce col proprio livello di ricerca * bonus per livello.
    // Bonus per livello è un array [metal, crystal, deut, metalCap, crystalCap, deutCap]
    // Edifici LF che amplificano le ricerche:
    //   1011 (Metropolis)  → +0.5%/livello     [metal/crystal/deut]
    //   3007 (HPT)         → +0.3%/livello     [crystal]
    //   3011 (Chip Mass)   → +0.4%/livello     [metal]
    //   4007 (Cloning Lab) → +0.25%/livello    [Kaelesh solo]
    const calcLFResearchBonus = (planets) => {
        if (!Array.isArray(planets) || planets.length === 0) return 0;
        const bonusPerc = { metal: 0, crystal: 0, deuterium: 0 };

        // Accumula bonus da ogni pianeta
        planets.forEach(p => {
            const lfData = p.lfResearch || {};
            const lfLevel = parseInt(p.lifeformLevel) || 0;
            const lifeformMult = 1 + 0.001 * lfLevel; // 0.1% per lifeform level

            // Building multiplier per questo pianeta
            const bld = p.lfBuildings || {};
            const metroLvl = parseInt(bld['1011']) || 0;
            const hptLvl = parseInt(bld['3007']) || 0;
            const cmpLvl = parseInt(bld['3011']) || 0;
            const cloneLvl = parseInt(bld['4007']) || 0;
            const buildingsMult = 1 + (metroLvl * 0.005) + (hptLvl * 0.003) + (cmpLvl * 0.004);

            // Determina la categoria di ricerca corretta per questa lifeform
            const lfCatKey = `lf_${p.lifeform}_res`;
            const catData = OGAME_DB[lfCatKey];
            if (!catData) return;

            const isKaelesh = p.lifeform === 'kaelesh';
            const kaeleshBuildingMult = isKaelesh ? (1 + cloneLvl * 0.0025) : 1;

            const items = catData.items || {};
            for (const [idStr, itemData] of Object.entries(items)) {
                const level = parseInt(lfData[idStr]) || 0;
                if (level <= 0) continue;
                const bonus = itemData.bonus;
                if (!bonus) continue;
                const metalBonusPerLvl = bonus[0] || 0;
                const crystalBonusPerLvl = bonus[1] || 0;
                const deutBonusPerLvl = bonus[2] || 0;
                const metalCap = bonus[3] || 0;
                const crystalCap = bonus[4] || 0;
                const deutCap = bonus[5] || 0;

                const mult = buildingsMult * kaeleshBuildingMult * lifeformMult;

                let mb = Math.min(level * metalBonusPerLvl * mult, metalCap || Infinity);
                let cb = Math.min(level * crystalBonusPerLvl * mult, crystalCap || Infinity);
                let db = Math.min(level * deutBonusPerLvl * mult, deutCap || Infinity);

                bonusPerc.metal += mb;
                bonusPerc.crystal += cb;
                bonusPerc.deuterium += db;
            }
        });

        // Converti da frazione a percentuale (×100)
        return {
            metal: bonusPerc.metal * 100,
            crystal: bonusPerc.crystal * 100,
            deuterium: bonusPerc.deuterium * 100
        };
    };", "old_string": "    // Calcola il bonus produzione totale dalle ricerche LF per un set di pianeti.
