        // Schema classi: 1{lifeform}2{id_due_cifre} (es. 11202 = human research 202)
        // Container: lifeform1research, lifeform2research, lifeform3research, lifeform4research
        const extractLfResearchLevels = (p) => {
            const result = {};
            // lf_research_map: da ogame_db 4-digit ID a empire class prefix
            // es. 1102 → 112, 2107 → 122
            const lfMap = { 1100: '112', 1200: '122', 1300: '132', 1400: '142',
                           2100: '212', 2200: '222', 2300: '232', 2400: '242',  // non esistono
                           3100: '312', 3200: '322', 3300: '332', 3400: '342',
                           4100: '412', 4200: '422', 4300: '432', 4400: '442' };
            // Cerca i container corretti
            for (const container of ['lifeform1research', 'lifeform2research', 'lifeform3research', 'lifeform4research']) {
                const section = p.querySelector('.' + container);
                if (!section) continue;
                section.querySelectorAll('li').forEach(li => {
                    const cls = Array.from(li.classList).find(c => /^1\d{4}$/.test(c));
                    if (!cls) return;
                    const src = li.querySelector('a:not(.active)') || li.querySelector('span') || li;
                    const m = src.textContent.replace(/\./g, '').match(/\d+/);
                    if (!m) return;
                    const empireLvl = parseInt(m[0]);
                    if (empireLvl <= 0) return;
                    // Converti empire class a ogame_db ID: 11202 → 1102
                    const lfNum = parseInt(cls[1]);  // 11202: lifeform = 1
                    const typeNum = parseInt(cls[2]); // 11202: type = 2 (research)
                    const subId = parseInt(cls.slice(3)); // 11202: 02
                    const ogId = lfNum * 1000 + (typeNum === 2 ? 100 : 0) + subId;
                    result[String(ogId)] = empireLvl;
                });
            }
            return result;
        };

        // Estrae i livelli degli edifici amplificatori LF
        // Schema classi building: 1{lifeform}1{id_due_cifre} (es. 11111 = Metropolis)
        const extractAmpBuildings = (p) => {
            const result = {};
            const bldMap = {
                // Metropolis: 1011 → empire class 11111 in lifeform1buildings
                '1011': { container: 'lifeform1buildings', empireId: 11111 },
                // HPT: 3007 → empire class 13107 in lifeform3buildings
                '3007': { container: 'lifeform3buildings', empireId: 13107 },
                // Chip Mass: 3011 → empire class 13111 in lifeform3buildings
                '3011': { container: 'lifeform3buildings', empireId: 13111 },
                // Cloning Lab: 4007 → empire class 14107 in lifeform4buildings
                '4007': { container: 'lifeform4buildings', empireId: 14107 }
            };
            for (const [ogId, { container, empireId }] of Object.entries(bldMap)) {
                const section = p.querySelector('.' + container);
                if (!section) continue;
                const li = section.querySelector('li.' + empireId);
                if (!li) continue;
                const src = li.querySelector('a:not(.active)') || li.querySelector('span') || li;
                const m = src.textContent.replace(/\./g, '').match(/\d+/);
                if (m && parseInt(m[0]) > 0) result[ogId] = parseInt(m[0]);
